"analysis": {
  "author_purpose_zh": "既作为第 3 章各小节的导航图（每个方框对应 3.1–3.6 中的一节），又用箭头说明这些活动之间的流程关系：启动与规划是一次性的，阶段级三项活动循环执行，循环结束后才进入项目收尾。",
  "reading_sequence_zh": "先读左列自上而下：架构项目启动 → 架构项目规划。规划完成后箭头向右进入右列，开始阶段级循环：阶段规划 → 执行、监控与控制阶段 → 阶段收尾；阶段收尾右侧的箭头向上折回阶段规划，旁标 n，表示对每个阶段重复。循环结束后，从阶段收尾向左下箭头进入架构项目收尾。",
  "source_logic_zh": [
    "项目启动与项目规划是项目级、一次性活动；阶段规划、执行监控、阶段收尾是阶段级、重复 n 次的活动。",
    "阶段级循环的顺序是“先规划本阶段，再执行监控，最后收尾”，收尾后又回到下一阶段的规划。",
    "架构项目收尾只在阶段循环结束后发生，且由“阶段收尾”触发，而不是与阶段收尾并行。",
    "六个方框与第 3 章的 3.1–3.6 节一一对应，因此这张图也是本章的阅读路线图。",
    "图中没有画 ADM 阶段；ADM 的对应关系在图 2-2 中用圆盘表达，这里只保留项目管理活动。"
  ],
  "structure_findings_zh": [
    "本图有 7 个具名或隐含元素、6 条关系和 0 条包含/分组记录。",
    "本图没有可直接确认为人员直属汇报的关系；视觉上下位置、能力分解和治理职责分别读取。",
    "包含分组后有 2 个连通分量；分离可能源于图例、并列分类或独立示例，未自动补边。"
  ],
  "application_zh": [
    "按阶段/事件/行为关系读取入口、出口、责任和产物；检查循环与例外路径。",
    "工作流先后不表示组织管理权；在项目中显式记录条件和完成标准。"
  ],
  "hierarchy_explanation_zh": "两层：左列是项目级活动（启动、规划、收尾），右列是阶段级活动（阶段规划、执行监控、阶段收尾）。阶段级活动整体处于“项目规划之后、项目收尾之前”的时间段内，并通过 n 次回路重复；图中没有组织上下级。",
  "line_explanation_zh": "实线箭头表示流程先后：启动→规划、规划→阶段规划、阶段规划→执行监控→阶段收尾、阶段收尾→项目收尾。右侧折线箭头从阶段收尾回到阶段规划，表示循环，n 表示重复次数。没有虚线、没有并行分支。",
  "misreadings_zh": [
    "不要把“阶段规划”理解为规划某个 ADM 阶段；本文档中 stage 指项目阶段，一个项目阶段可覆盖多个 ADM 阶段。",
    "不要以为架构项目收尾与阶段收尾是同一件事：阶段收尾每个阶段都做，项目收尾只在最后做一次。",
    "不要把 n 理解为固定次数；它是“对每个阶段重复”的占位符号。",
    "中文稿引用的重绘 SVG 增加了副标题和“说明”，阅读时不要把那些补充文字当作原图内容。"
  ],
